class Solution
{
public:
    bool validWordSquare(vector<string>& words)
    {
        for (int r = 0; r < (int)words.size(); ++r)
        {
            for (int c = 0; c < (int)words[r].size(); ++c)
            {
                if (c >= (int)words.size() ||
                    r >= (int)words[c].size() ||
                    words[r][c] != words[c][r])
                    {
                    return false;
                }
            }
        }
        return true;
    }
};
